import random
from typing import List

# Data type: 1-bpp bitmap bytes
# - Packed MSB-first, no header
# - Must provide at least ceil(w*h/8) bytes
# Fuzzer stub will choose w,h so that w*h <= 8*len(buf) and within canvas.
# Our goal: return interesting, valid bitmap payloads of varying sizes (1..4096 bytes).

_MAX_BYTES = 4096
_MIN_BYTES = 1

# Predefined interesting 1-bpp patterns (MSB-first per byte)
_PRESETS: List[bytes] = [
    # All zeros (fully transparent)
    bytes([0x00]) * 32,
    # All ones (fully set)
    bytes([0xFF]) * 32,
    # Alternating bits 1010... and 0101...
    (bytes([0xAA]) * 16) + (bytes([0x55]) * 16),
    # Vertical stripes: bytes alternate 0xF0/0x0F
    (bytes([0xF0]) * 16) + (bytes([0x0F]) * 16),
    # Horizontal stripes: blocks of 0xFF and 0x00
    (bytes([0xFF]) * 8) + (bytes([0x00]) * 8) + (bytes([0xFF]) * 8) + (bytes([0x00]) * 8),
    # Checkerboard period-2 (AA/55 repeated)
    bytes([0xAA, 0x55]) * 32,
    # Diagonal-like pattern
    bytes([0x80, 0x40, 0x20, 0x10, 0x08, 0x04, 0x02, 0x01]) * 4,
]

# Generate a procedural pattern of given size
def _gen_pattern(n: int, rng: random.Random) -> bytes:
    mode = rng.randrange(0, 8)
    out = bytearray(n)
    if mode == 0:
        # Random bytes
        for i in range(n):
            out[i] = rng.getrandbits(8)
    elif mode == 1:
        # Repeating short motif of random length 1..8
        motif_len = rng.randint(1, 8)
        motif = bytes(rng.getrandbits(8) for _ in range(motif_len))
        for i in range(n):
            out[i] = motif[i % motif_len]
    elif mode == 2:
        # Gradually shifting bit mask MSB-first
        b = 0x80
        for i in range(n):
            out[i] = b
            b >>= 1
            if b == 0:
                b = 0x80
    elif mode == 3:
        # Blocks of 0x00 and 0xFF with random block sizes
        i = 0
        val = 0xFF
        while i < n:
            block = rng.randint(1, 32)
            for j in range(min(block, n - i)):
                out[i + j] = val
            i += block
            val ^= 0xFF
    elif mode == 4:
        # Alternating nibbles
        a = rng.choice([0xF0, 0x0F, 0xAA, 0x55, 0xCC, 0x33])
        b = a ^ 0xFF
        for i in range(n):
            out[i] = a if (i & 1) == 0 else b
    elif mode == 5:
        # Sparse pixels: mostly zeros with occasional single-bit set
        density = rng.choice([2, 4, 8, 16, 32])  # one set bit per k bytes on avg
        for i in range(n):
            if rng.randrange(density) == 0:
                out[i] = 1 << rng.randrange(8)
            else:
                out[i] = 0
    elif mode == 6:
        # Dense pixels: mostly ones with occasional cleared single bit
        density = rng.choice([2, 4, 8, 16, 32])
        for i in range(n):
            if rng.randrange(density) == 0:
                out[i] = 0xFF ^ (1 << rng.randrange(8))
            else:
                out[i] = 0xFF
    else:
        # Staircase nibble fill
        val = 0
        for i in range(n):
            out[i] = ((val & 0x0F) << 4) | (val & 0x0F)
            val = (val + 1) & 0x0F
    return bytes(out)

# Generate a size chosen to lead to varied w*h in the stub while staying <= 4096
def _choose_size(rng: random.Random) -> int:
    # Favor sizes that are multiples of common widths (bytes/row) to explore rectangular areas
    choices = []
    # Common byte-per-row values for widths 8,16,24,32,64, etc.
    for row_bytes in [1, 2, 3, 4, 8, 12, 16, 24, 32, 64, 128, 256]:
        height = rng.randint(1, max(1, 4096 // row_bytes))
        size = row_bytes * height
        if _MIN_BYTES <= size <= _MAX_BYTES:
            choices.append(size)
    # Include some primes and powers for edge cases
    choices += [
        1, 2, 3, 5, 7, 11, 13, 17, 31, 63, 127, 255, 257, 509, 1021,
        32, 64, 128, 192, 256, 384, 512, 768, 1024, 1536, 2048, 3072, 4096
    ]
    # Keep within bounds
    choices = [c for c in choices if _MIN_BYTES <= c <= _MAX_BYTES]
    return rng.choice(choices)

def generate(seed: int) -> bytes:
    rng = random.Random(seed)

    # Decide between preset and procedural
    use_preset = rng.random() < 0.35

    if use_preset:
        preset = rng.choice(_PRESETS)
        # Optionally resize preset by repeating or trimming to a chosen size
        target_size = _choose_size(rng)
        if len(preset) == target_size:
            data = preset
        elif len(preset) < target_size:
            reps = (target_size + len(preset) - 1) // len(preset)
            data = (preset * reps)[:target_size]
        else:
            data = preset[:target_size]
        return bytes(data)
    else:
        size = _choose_size(rng)
        return _gen_pattern(size, rng)

