    # XBM is packed LSB-first per byte, row-major. We'll fill bit-by-bit.
    nbits = width * height
    out = bytearray((nbits + 7) // 8)
    byte = 0
    bitpos = 0
    idx = 0
    for y in range(height):
        for x in range(width):
            on = ((x // tile_w) + (y // tile_h)) & 1
            if on:
                byte |= (1 << (bitpos))
            bitpos += 1
            if bitpos == 8:
                out[idx] = byte
                idx += 1
                byte = 0
                bitpos = 0
    if bitpos != 0:
        out[idx] = byte
    return bytes(out)


def _make_stripes(width: int, height: int, horizontal: bool, period: int, duty_num: int, duty_den: int) -> bytes:
    # Stripes: horizontal or vertical with specified period and duty cycle
    nbits = width * height
    out = bytearray((nbits + 7) // 8)
    byte = 0
    bitpos = 0
    idx = 0
    for y in range(height):
        for x in range(width):
            pos = y if horizontal else x
            phase = pos % max(1, period)
            on = 1 if (phase * duty_den < duty_num * period) else 0
            if on:
                byte |= (1 << bitpos)
            bitpos += 1
            if bitpos == 8:
                out[idx] = byte
                idx += 1
                byte = 0
                bitpos = 0
    if bitpos != 0:
        out[idx] = byte
    return bytes(out)


def _make_random_sparse(width: int, height: int, p_on_num: int, p_on_den: int, rng: random.Random) -> bytes:
    # Random mask with probability p_on of 1 bits
    nbits = width * height
    out = bytearray((nbits + 7) // 8)
    byte = 0
    bitpos = 0
    idx = 0
    for _y in range(height):
        for _x in range(width):
            on = 1 if rng.randrange(p_on_den) < p_on_num else 0
            if on:
                byte |= (1 << bitpos)
            bitpos += 1
            if bitpos == 8:
                out[idx] = byte
                idx += 1
                byte = 0
                bitpos = 0
    if bitpos != 0:
        out[idx] = byte
    return bytes(out)


def _choose_dims_from_budget(rng: random.Random, max_bytes: int) -> (int, int):
    # Choose a width and height such that ceil(w*h/8) <= max_bytes
    # Bias toward a variety of shapes, including wide, tall, and square-ish
    if max_bytes <= 0:
        return 1, 1
    max_bits = max_bytes * 8
    # Choose an area target
    area = rng.randint(1, max_bits)
    # Choose a width; ensure at least 1
    # Favor powers of two and smallish widths sometimes
    choices: List[int] = [1, 2, 3, 4, 7, 8, 9, 15, 16, 24, 32, 48, 64, 96, 128, 160, 240, 320]
    w = choices[rng.randrange(len(choices))] if rng.random() < 0.6 else max(1, int(rng.gammavariate(2.0, 16.0)))
    # Clamp width so height stays >=1
    w = max(1, min(w, area))
    h = max(1, area // w)
    # Trim if over budget
    # Ensure ceil(w*h/8) <= max_bytes
    while ((w * h + 7) // 8) > max_bytes and h > 1:
        h -= 1
    while ((w * h + 7) // 8) > max_bytes and w > 1:
        w -= 1
    if w < 1:
        w = 1
    if h < 1:
        h = 1
    return w, h


def _pack_bits_matrix_to_bytes(bits: List[List[int]]) -> bytes:
    # Helper to pack a user-provided bit matrix [y][x] LSB-first row-major
    height = len(bits)
    width = len(bits[0]) if height else 0
    nbits = width * height
    out = bytearray((nbits + 7) // 8)
    byte = 0
    bitpos = 0
    idx = 0
    for y in range(height):
        row = bits[y]
        for x in range(width):
            if row[x]:
                byte |= (1 << bitpos)
            bitpos += 1
            if bitpos == 8:
                out[idx] = byte
                idx += 1
                byte = 0
                bitpos = 0
    if bitpos != 0:
        out[idx] = byte
    return bytes(out)


def _make_shapes(width: int, height: int, rng: random.Random) -> bytes:
    # Compose a mask with some geometric shapes to exercise drawing logic
    # We'll draw rectangles and simple diagonals in 1-bpp matrix then pack.
    bits = [[0 for _ in range(width)] for _ in range(height)]

    def rect(x0, y0, w, h, fill):
        for yy in range(max(0, y0), min(height, y0 + h)):
            for xx in range(max(0, x0), min(width, x0 + w)):
                if fill:
                    bits[yy][xx] = 1
                else:
                    if (yy == y0 or yy == y0 + h - 1 or xx == x0 or xx == x0 + w - 1):
                        bits[yy][xx] = 1

    # Random rectangles
    for _ in range(rng.randint(1, 4)):
        rw = max(1, rng.randint(1, max(1, width // 2)))
        rh = max(1, rng.randint(1, max(1, height // 2)))
        x0 = rng.randint(0, max(0, width - rw)) if width - rw >= 0 else 0
        y0 = rng.randint(0, max(0, height - rh)) if height - rh >= 0 else 0
        rect(x0, y0, rw, rh, fill=rng.random() < 0.6)

    # Diagonals
    if width > 1 and height > 1:
        for i in range(min(width, height)):
            if rng.random() < 0.8:
                bits[i][i] = 1
            if rng.random() < 0.5:
                bits[height - 1 - i][i] = 1

    return _pack_bits_matrix_to_bytes(bits)


def generate(seed: int) -> bytes:
    rng = random.Random(seed)

    # Decide overall strategy/pattern
    pattern = rng.choices(
        population=[
            'solid0', 'solid1', 'checker_small', 'checker_big',
            'stripes_h', 'stripes_v', 'random_sparse', 'random_dense',
            'shapes'
        ],
        weights=[5, 5, 6, 4, 6, 6, 5, 5, 8],
        k=1
    )[0]

    # Choose dimensions under budget; allow full budget often but sometimes smaller
    budget = rng.randint(8, MAX_BYTES) if rng.random() < 0.85 else rng.randint(1, min(128, MAX_BYTES))
    w, h = _choose_dims_from_budget(rng, budget)

    # Generate content
    if pattern == 'solid0':
        data = _make_solid(w, h, 0)
    elif pattern == 'solid1':
        data = _make_solid(w, h, 1)
    elif pattern == 'checker_small':
        tw = rng.choice([1, 2, 3, 4])
        th = rng.choice([1, 2, 3, 4])
        data = _make_checker(w, h, tw, th)
    elif pattern == 'checker_big':
        tw = max(1, w // rng.choice([2, 3, 4, 5]))
        th = max(1, h // rng.choice([2, 3, 4, 5]))
        data = _make_checker(w, h, tw, th)
    elif pattern == 'stripes_h':
        period = rng.choice([2, 3, 4, 5, 6, 8, 12, 16])
        duty_den = rng.choice([2, 3, 4, 5, 8])
        duty_num = rng.randint(1, duty_den)
        data = _make_stripes(w, h, horizontal=True, period=period, duty_num=duty_num, duty_den=duty_den)
    elif pattern == 'stripes_v':
        period = rng.choice([2, 3, 4, 5, 6, 8, 12, 16])
        duty_den = rng.choice([2, 3, 4, 5, 8])
        duty_num = rng.randint(1, duty_den)
        data = _make_stripes(w, h, horizontal=False, period=period, duty_num=duty_num, duty_den=duty_den)
    elif pattern == 'random_sparse':
        data = _make_random_sparse(w, h, p_on_num=1, p_on_den=8, rng=rng)
    elif pattern == 'random_dense':
        data = _make_random_sparse(w, h, p_on_num=6, p_on_den=8, rng=rng)
    else:  # 'shapes'
        data = _make_shapes(w, h, rng)

    # Safety clamp
    if len(data) > MAX_BYTES:
        data = data[:MAX_BYTES]

    return bytes(data)

import random
from typing import List

# Data type: 8-bpp grayscale bitmap bytes
# Requirement from stub: provide a non-empty buffer; when used with chosen w,h,
# the fuzzer ensures w*h <= len(buf). We should return interesting but valid
# grayscale pixel streams (row-major, no header), exploring patterns and ranges.

MAX_BYTES = 4096


def _r(seed: int) -> random.Random:
    return random.Random(seed)


def _solid_gray(length: int, value: int) -> bytes:
    return bytes([value & 0xFF]) * length


def _horizontal_gradient(width: int, height: int) -> bytes:
    # left-to-right gradient per row
    if width <= 1:
        row = bytes([0]) * width
    else:
        row = bytes(int(255 * x / (width - 1)) for x in range(width))
    return row * height


def _vertical_gradient(width: int, height: int) -> bytes:
    # top-to-bottom gradient per column
    out = bytearray(width * height)
    for y in range(height):
        val = int(255 * y / (height - 1)) if height > 1 else 0
        start = y * width
        out[start:start + width] = bytes([val]) * width
    return bytes(out)


def _checkerboard(width: int, height: int, tile_w: int, tile_h: int,
                  v0: int = 0x10, v1: int = 0xE0) -> bytes:
    out = bytearray(width * height)
    for y in range(height):
        for x in range(width):
            cx = (x // max(1, tile_w)) & 1
            cy = (y // max(1, tile_h)) & 1
            out[y * width + x] = v0 if (cx ^ cy) == 0 else v1
    return bytes(out)


def _stripes(width: int, height: int, vertical: bool, period: int,
             a: int = 0x00, b: int = 0xFF) -> bytes:
    out = bytearray(width * height)
    period = max(1, period)
    for y in range(height):
        for x in range(width):
            t = (x if vertical else y) // period
            out[y * width + x] = a if (t & 1) == 0 else b
    return bytes(out)


def _ramps_palette(width: int, height: int, steps: int) -> bytes:
    # Tiled palette ramps to exercise many distinct grayscale values
    steps = max(2, min(256, steps))
    palette = [int(i * 255 / (steps - 1)) for i in range(steps)]
    out = bytearray(width * height)
    idx = 0
    for y in range(height):
        for x in range(width):
            out[idx] = palette[(x + y) % steps]
            idx += 1
    return bytes(out)


def _noise(width: int, height: int, rng: random.Random) -> bytes:
    return bytes(rng.randrange(256) for _ in range(width * height))


def _rings(width: int, height: int, cx: int, cy: int, period: int) -> bytes:
    # Concentric rings pattern centered at (cx,cy)
    out = bytearray(width * height)
    period = max(1, period)
    for y in range(height):
        for x in range(width):
            dx = x - cx
            dy = y - cy
            d = int((dx * dx + dy * dy) ** 0.5)
            v = 0xFF if ((d // period) & 1) else 0x00
            out[y * width + x] = v
    return bytes(out)


def _choose_dims(rng: random.Random, max_pixels: int) -> (int, int):
    # Favor a spread of aspect ratios and sizes while keeping w*h within limit
    # Try some biased choices first
    choices = []
    # Common small tiles
    choices += [(8, 8), (16, 16), (32, 32), (64, 64)]
    # Wide banners
    choices += [(64, 8), (96, 16), (128, 16)]
    # Tall strips
    choices += [(8, 64), (16, 96), (16, 128)]
    # Edge cases
    choices += [(1, 1), (1, 64), (64, 1)]
    choices = [wh for wh in choices if wh[0] * wh[1] <= max_pixels]
    if choices and rng.random() < 0.6:
        return rng.choice(choices)
    # Otherwise generate random dims constrained by max_pixels
    # Pick width, then cap height
    max_w = max(1, min(256, max_pixels))
    w = rng.randint(1, max_w)
    max_h = max(1, max_pixels // w)
    h = rng.randint(1, max_h)
    return w, h


def _pattern_bytes(rng: random.Random, width: int, height: int) -> bytes:
    # Select a pattern type
    patterns = [
        "solid", "hgrad", "vgrad", "checker", "vstripes", "hstripes",
        "ramps", "noise", "rings"
    ]
    p = rng.choice(patterns)
    if p == "solid":
        # Choose interesting gray levels
        value = rng.choice([0x00, 0xFF, 0x7F, 0x01, 0xFE, rng.randrange(256)])
        return _solid_gray(width * height, value)
    elif p == "hgrad":
        return _horizontal_gradient(width, height)
    elif p == "vgrad":
        return _vertical_gradient(width, height)
    elif p == "checker":
        tw = rng.choice([1, 2, 3, 4, 8, 16])
        th = rng.choice([1, 2, 3, 4, 8, 16])
        v0 = rng.choice([0x00, 0x10, 0x40])
        v1 = rng.choice([0xFF, 0xE0, 0xBF])
        return _checkerboard(width, height, tw, th, v0, v1)
    elif p == "vstripes":
        period = rng.choice([1, 2, 3, 4, 8, 16, 32])
        return _stripes(width, height, True, period,
                        rng.choice([0x00, 0x20, 0x7F]),
                        rng.choice([0xFF, 0xDF, 0x80]))
    elif p == "hstripes":
        period = rng.choice([1, 2, 3, 4, 8, 16, 32])
        return _stripes(width, height, False, period,
                        rng.choice([0x00, 0x20, 0x7F]),
                        rng.choice([0xFF, 0xDF, 0x80]))
    elif p == "ramps":
        steps = rng.choice([4, 8, 16, 32, 64, 128, 256])
        return _ramps_palette(width, height, steps)
    elif p == "noise":
        return _noise(width, height, rng)
    elif p == "rings":
        period = rng.choice([2, 3, 4, 6, 8, 12, 16])
        cx = rng.randrange(width)
        cy = rng.randrange(height)
        return _rings(width, height, cx, cy, period)
    else:
        return _noise(width, height, rng)


def generate(seed: int) -> bytes:
    rng = _r(seed)

    # Decide total bytes to emit, up to MAX_BYTES
    # For 8-bpp, length should generally be a multiple of a plausible width,
    # but the stub will compute h from len/w, so any length > 0 is acceptable.
    # We will synthesize a width and height then fill w*h bytes; if result
    # exceeds MAX_BYTES, we reduce dims.
    max_pixels = MAX_BYTES

    # Pick dimensions that keep within max size
    w, h = _choose_dims(rng, max_pixels)

    data = _pattern_bytes(rng, w, h)
    # Ensure size does not exceed limit and is non-empty
    if not data:
        data = b"\x00"
    if len(data) > MAX_BYTES:
        data = data[:MAX_BYTES]

    return bytes(data)

import random
import string
from typing import List

# Target: Provide interesting, valid C-strings for Adafruit_GFX::getTextBounds
# FUZZ_PARAM_STR consumes the entire buffer as a std::string, so we generate
# text without embedded NULs. Input should be valid UTF-8/ASCII and under 4096 bytes.

MAX_SIZE = 4096

ASCII_PRINTABLE = ''.join(chr(c) for c in range(32, 127))
ASCII_WHITESPACE = '\t\n\r\v\f '
ASCII_CONTROLS = ''.join(chr(c) for c in range(1, 32) if c not in (9, 10, 13))

# Some useful UTF-8 sequences (multi-byte) to exercise non-ASCII code paths.
UTF8_SAMPLES = [
    '€',     # Euro sign (3-byte)
    '£',     # Pound (2-byte)
    '©',     # Copyright (2-byte)
    '™',     # TM (3-byte)
    '–—',    # en/em dash
    '…',     # ellipsis
    'àáâäãå',
    'ç', 'ñ', 'ø', 'þ', 'ß',
    'ÄÖÜäöü',
    'Ωμ',     # Greek
    '✓✗★☆',  # symbols
]

REPETITIVE_SETS = [
    'WWWWWWWW', 'iiiiiiii', 'MMMMMMMM', 'llllllll', 'OO00OO00',
    '1234567890', 'AaBbCcDdEeFfGg',
]

WORDS = [
    'Hello, world!',
    'Adafruit GFX',
    'Quick brown fox',
    '0123456789',
    'wrap test line one',
    'CP437 test',
]

PUNCT_BLOCK = string.punctuation


def _rand_ascii_block(rng: random.Random, length: int) -> str:
    # Mix printable, whitespace, and some controls (avoid NUL)
    if length <= 0:
        return ''
    choices = ASCII_PRINTABLE + ASCII_WHITESPACE
    out = []
    for _ in range(length):
        if rng.random() < 0.05 and ASCII_CONTROLS:
            out.append(rng.choice(ASCII_CONTROLS))
        else:
            out.append(rng.choice(choices))
    return ''.join(out)


def _utf8_mixture(rng: random.Random, target_len: int) -> str:
    if target_len <= 0:
        return ''
    parts: List[str] = []
    while len(''.join(parts).encode('utf-8')) < target_len:
        choice = rng.random()
        if choice < 0.5:
            parts.append(_rand_ascii_block(rng, rng.randint(3, 12)))
        elif choice < 0.8:
            parts.append(rng.choice(UTF8_SAMPLES))
        else:
            parts.append(rng.choice(REPETITIVE_SETS))
        # Occasionally add punctuation clusters and whitespace
        if rng.random() < 0.3:
            parts.append(rng.choice([' ', '  ', '\t', '\n']))
        if rng.random() < 0.2:
            parts.append(''.join(rng.choice(PUNCT_BLOCK) for _ in range(rng.randint(1, 4))))
    return ''.join(parts)


def _make_lines(rng: random.Random) -> str:
    num_lines = rng.randint(1, 6)
    lines = []
    for _ in range(num_lines):
        style = rng.randint(0, 4)
        if style == 0:
            lines.append(rng.choice(WORDS))
        elif style == 1:
            lines.append(rng.choice(REPETITIVE_SETS))
        elif style == 2:
            lines.append(_rand_ascii_block(rng, rng.randint(5, 40)))
        elif style == 3:
            lines.append(_utf8_mixture(rng, rng.randint(8, 64)))
        else:
            lines.append(''.join(rng.choice('WMi l0O|') for _ in range(rng.randint(8, 24))))
    return '\n'.join(lines)


def _make_interesting_string(rng: random.Random, budget: int) -> str:
    if budget <= 0:
        return ''
    scenario = rng.randint(0, 7)
    if scenario == 0:
        s = ''
    elif scenario == 1:
        s = rng.choice(['A', 'i', 'W', '0', 'O', '|'])
    elif scenario == 2:
        s = _rand_ascii_block(rng, rng.randint(1, max(1, budget // 4)))
    elif scenario == 3:
        s = _utf8_mixture(rng, rng.randint(8, max(8, budget // 2)))
    elif scenario == 4:
        s = _make_lines(rng)
    elif scenario == 5:
        s = ''.join(rng.choice(PUNCT_BLOCK + ' ') for _ in range(rng.randint(5, max(5, budget // 3))))
    elif scenario == 6:
        narrow = 'il.!|:'
        wide = 'MW@#%'
        n = rng.randint(6, min(120, max(6, budget)))
        s = ''.join((rng.choice(wide) if i % 2 == 0 else rng.choice(narrow)) for i in range(n))
    else:
        s = ' '.join(rng.choice(WORDS + UTF8_SAMPLES) for _ in range(rng.randint(2, 10)))

    # Ensure size within budget and avoid internal NULs
    b = s.encode('utf-8', errors='ignore')
    if len(b) > budget:
        b = b[:budget]
        # Backtrack to valid UTF-8 boundary
        cut = len(b)
        while cut > 0:
            try:
                s = b[:cut].decode('utf-8')
                break
            except UnicodeDecodeError:
                cut -= 1
        else:
            s = ''
    s = s.replace('\x00', '')
    return s


def generate(seed: int) -> bytes:
    rng = random.Random(seed)
    # Budget for the entire string
    budget = rng.randint(16, min(1024, MAX_SIZE))

    segments: List[str] = []
    while True:
        used = len(''.join(segments).encode('utf-8'))
        remaining = budget - used
        if remaining <= 0:
            break
        # Choose a safe range for seg_budget ensuring low <= high
        low = 1 if remaining < 4 else min(remaining, 64) // 2
        low = max(1, low)
        high = min(remaining, 128)
        if low > high:
            low = 1
            high = remaining
        seg_budget = rng.randint(low, high)
        segments.append(_make_interesting_string(rng, seg_budget))
        if rng.random() < 0.4 and remaining > 1:
            segments.append('\n')

    s = ''.join(segments)
    b = s.encode('utf-8', errors='ignore')[:MAX_SIZE]
    if b"\x00" in b:
        b = b.replace(b"\x00", b"")
    return b
